import { test, expect } from '@playwright/test';

test.describe('Table Empty State Illustration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should display empty state illustration when table has no data', async ({ page }) => {
    // Wait for the table to load
    await page.waitForLoadState('networkidle');

    // Check if empty state illustration is visible
    const emptyStateIllustration = page.getByRole('img', { name: /no data|empty state/i });
    await expect(emptyStateIllustration).toBeVisible();
  });

  test('should display empty state message text when table is empty', async ({ page }) => {
    // Wait for the table to load
    await page.waitForLoadState('networkidle');

    // Check for empty state message
    const emptyMessage = page.getByText(/no data available|table is empty|no records found/i);
    await expect(emptyMessage).toBeVisible();
  });

  test('should not display table rows when data is empty', async ({ page }) => {
    // Wait for the table to load
    await page.waitForLoadState('networkidle');

    // Verify no table rows are present
    const tableRows = page.getByRole('row');
    const rowCount = await tableRows.count();

    // Should only have header row or no rows at all
    expect(rowCount).toBeLessThanOrEqual(1);
  });

  test('should display empty state container with proper styling', async ({ page }) => {
    // Wait for the table to load
    await page.waitForLoadState('networkidle');

    // Check for empty state container
    const emptyStateContainer = page.getByRole('region', { name: /empty|no data/i });
    await expect(emptyStateContainer).toBeVisible();

    // Verify it's properly displayed (not hidden or zero opacity)
    const isVisible = await emptyStateContainer.isVisible();
    expect(isVisible).toBe(true);
  });

  test('should hide empty state when data is loaded', async ({ page }) => {
    // Wait for the table to load
    await page.waitForLoadState('networkidle');

    // Initially empty state should be visible
    const emptyStateIllustration = page.getByRole('img', { name: /no data|empty state/i });
    await expect(emptyStateIllustration).toBeVisible();

    // Simulate loading data by clicking a load button if available
    const loadButton = page.getByRole('button', { name: /load|refresh|fetch/i });
    if (await loadButton.isVisible()) {
      await loadButton.click();
      await page.waitForLoadState('networkidle');

      // Empty state should be hidden after data loads
      await expect(emptyStateIllustration).not.toBeVisible();
    }
  });
});
